#!/usr/bin/env bash
# Auto-generated by publish DAG analysis. Regenerate if dependencies change.
#
# Tier 0 = crates with no internal workspace dependencies (publishable now).
# Full plan is in publish-plan.txt alongside this script.
#
# Prerequisites:
#   cargo login                        (once, if not authenticated)
#   each crate name is available on crates.io  (cargo search <crate>)
#
# Per-crate procedure:
#   cargo publish --dry-run -p <crate>   (manifest validate; already green)
#   cargo publish -p <crate>             (with full verify build)
#   verify crates.io page shows the version
#   advance to next crate
#
# A published version cannot be un-published; only yanked. A bug that
# surfaces after publish requires a patch bump (0.1.28) — the 0.1.27
# slot is gone forever. Pause at each gate and verify.
set -u

TIER0=(
  kod-ast
  kod-lsp
  kod-mcp
  kod-minimize
  kod-risk
  kod-schema-dialect
  kod-stats
  kod-telemetry
  kod-types
)

echo "Publishing ${#TIER0[@]} tier-0 crates: ${TIER0[*]}"
echo ""

i=0
for crate in "${TIER0[@]}"; do
  i=$((i + 1))
  echo ""
  echo "==============================================================="
  echo "  [$i/${#TIER0[@]}] NEXT: $crate"
  echo "==============================================================="
  echo "  Command:"
  echo "    cargo publish -p $crate"
  echo ""
  echo "  Before running, optionally re-validate with:"
  echo "    cargo publish --dry-run -p $crate"
  echo ""
  read -p "  Press enter when $crate is live on crates.io (Ctrl-C to abort): " _
done

echo ""
echo "Tier 0 complete. Update publish-plan.txt progress and run tier 1 next."
